fun getCandiesEaten(n: Int, k: Int): Int {
    if (n == 1) return 0
    var nVar = n - 1
    var candies = 1
    var sum = 2
    var consumed = 0
    while (nVar > 0) {
        while (candies <= k) {
            candies += sum
            sum++
            nVar--
        }
        val candiesToSubtract = candies - k
        nVar -= candiesToSubtract
        consumed += candiesToSubtract
        candies -= candiesToSubtract
    }
    return consumed
}

fun main() {
    val (n, k) = readln().split(" ").map { it.toInt() }
    println(getCandiesEaten(n, k))
}

